     1→/**
     2→ * Claude model profiles for Tokalator MCP.
     3→ * Scoped to Anthropic models only.
     4→ */
     5→
     6→export interface ModelProfile {
     7→  id: string;
     8→  label: string;
     9→  provider: 'anthropic';
    10→  contextWindow: number;
    11→  maxOutput: number;
    12→  rotThreshold: number;
    13→}
    14→
    15→export const MODEL_PROFILES: ModelProfile[] = [
    16→  { id: 'claude-opus-4.6',   label: 'Claude Opus 4.6',   provider: 'anthropic', contextWindow: 1_000_000, maxOutput: 32_000, rotThreshold: 40 },
    17→  { id: 'claude-sonnet-4.5', label: 'Claude Sonnet 4.5', provider: 'anthropic', contextWindow:   200_000, maxOutput: 16_000, rotThreshold: 20 },
    18→  { id: 'claude-sonnet-4',   label: 'Claude Sonnet 4',   provider: 'anthropic', contextWindow:   200_000, maxOutput: 16_000, rotThreshold: 20 },
    19→  { id: 'claude-haiku-4.5',  label: 'Claude Haiku 4.5',  provider: 'anthropic', contextWindow:   200_000, maxOutput: 64_000, rotThreshold: 15 },
    20→];
    21→
    22→export const DEFAULT_MODEL_ID = 'claude-opus-4.6';
    23→
    24→/**
    25→ * Find a model by partial ID or label match.
    26→ * Priority: exact id → exact label → startsWith → contains.
    27→ */
    28→export function findModel(query: string): ModelProfile | undefined {
    29→  const q = query.toLowerCase().replace(/[^a-z0-9.]/g, '');
    30→  if (!q) return undefined;
    31→
    32→  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9.]/g, '');
    33→
    34→  return (
    35→    MODEL_PROFILES.find(m => norm(m.id) === q) ||
    36→    MODEL_PROFILES.find(m => norm(m.label) === q) ||
    37→    MODEL_PROFILES.find(m => norm(m.id).startsWith(q) || norm(m.label).startsWith(q)) ||
    38→    MODEL_PROFILES.find(m => norm(m.id).includes(q) || norm(m.label).includes(q))
    39→  );
    40→}
    41→
    42→/** Get model by exact ID, falling back to default. */
    43→export function getModel(id: string): ModelProfile {
    44→  return (
    45→    MODEL_PROFILES.find(m => m.id === id) ||
    46→    MODEL_PROFILES.find(m => m.id === DEFAULT_MODEL_ID)!
    47→  );
    48→}
