    12→
    13→const require = createRequire(import.meta.url);
    14→
    15→export type TokenizerType = 'claude-bpe' | 'heuristic';
    16→
    17→export class TokenizerService {
    18→
    19→  private claudeTokenizer: Tiktoken | null = null;
    20→
    21→  getTokenizerType(): TokenizerType {
    22→    return 'claude-bpe';
    23→  }
    24→
    25→  getTokenizerLabel(): string {
    26→    return 'Claude BPE tokenizer';
    27→  }
    28→
    29→  /**
    30→   * Count tokens in text using the real Claude BPE tokenizer.
    31→   * Falls back to heuristic if the tokenizer fails to load.
    32→   */
    33→  countTokens(text: string): number {
    34→    try {
    35→      return this.countClaude(text);
    36→    } catch {
    37→      return this.heuristic(text);
    38→    }
    39→  }
    40→
    41→  /**
    42→   * Estimate tokens from raw byte size.
    43→   * Useful for workspace scanning without reading file contents.
    44→   */
    45→  estimateFromBytes(bytes: number): number {
    46→    return Math.ceil(bytes / 3.7);
    47→  }
    48→
    49→  private countClaude(text: string): number {
    50→    if (!this.claudeTokenizer) {
    51→      // Lazy-load Claude BPE ranks (696 KB JSON) on first use
    52→      const ranks = require('@anthropic-ai/tokenizer/claude.json');
    53→      this.claudeTokenizer = new Tiktoken(ranks);
    54→    }
    55→    return this.claudeTokenizer.encode(text.normalize('NFKC')).length;
    56→  }
    57→
    58→  private heuristic(text: string): number {
    59→    return Math.ceil(text.length / 4);
    60→  }
    61→
    62→  dispose(): void {
    63→    this.claudeTokenizer = null;
    64→  }
    65→}
