     1→/**
     2→ * Token budget estimator for MCP — operates on plain file paths.
     3→ * No VS Code dependencies.
     4→ */
     5→
     6→import { readFileSync } from 'fs';
     7→import { TokenizerService } from './tokenizerService.js';
     8→import { BudgetBreakdown } from './types.js';
     9→
    10→export interface FileBudget {
    11→  path: string;
    12→  tokens: number;
    13→  error?: string;
    14→}
    15→
    16→export class BudgetEstimator {
    17→
    18→  constructor(private readonly tokenizer: TokenizerService) {}
    19→
    20→  /**
    21→   * Count tokens in a file by reading it from disk.
    22→   */
    23→  countFileTokens(filePath: string): FileBudget {
    24→    try {
    25→      const content = readFileSync(filePath, 'utf-8');
    26→      return { path: filePath, tokens: this.tokenizer.countTokens(content) };
    27→    } catch (e) {
    28→      return { path: filePath, tokens: 0, error: String(e) };
    29→    }
    30→  }
    31→
    32→  /**
    33→   * Count tokens in a list of files.
    34→   */
    35→  countAllFiles(filePaths: string[]): FileBudget[] {
    36→    return filePaths.map(p => this.countFileTokens(p));
    37→  }
    38→
    39→  /**
    40→   * Estimate non-file overhead: system prompt + instructions + conversation + output reservation.
    41→   */
    42→  estimateOverhead(chatTurns: number, instructionFiles: number): number {
    43→    const systemPrompt = 2_000;
    44→    const instructionsCost = instructionFiles * 500;
    45→    const conversationCost = chatTurns * 800;
    46→    const outputReservation = 4_000;
    47→    return systemPrompt + instructionsCost + conversationCost + outputReservation;
    48→  }
    49→
    50→  /**
    51→   * Compute total budget usage and breakdown.
    52→   */
    53→  computeBudget(
    54→    files: FileBudget[],
    55→    chatTurns: number,
    56→    instructionFiles: number,
    57→    windowCapacity: number,
    58→  ): { used: number; capacity: number; percent: number; budgetLevel: 'low' | 'medium' | 'high'; breakdown: BudgetBreakdown } {
    59→    const fileTokens = files.reduce((sum, f) => sum + f.tokens, 0);
    60→    const overhead = this.estimateOverhead(chatTurns, instructionFiles);
    61→    const used = fileTokens + overhead;
    62→    const percent = Math.min((used / windowCapacity) * 100, 100);
    63→
    64→    const budgetLevel: 'low' | 'medium' | 'high' =
    65→      percent > 85 ? 'high' : percent > 60 ? 'medium' : 'low';
    66→
    67→    return {
    68→      used,
    69→      capacity: windowCapacity,
    70→      percent,
    71→      budgetLevel,
    72→      breakdown: {
    73→        files: fileTokens,
    74→        systemPrompt: 2_000,
    75→        instructions: instructionFiles * 500,
    76→        conversation: chatTurns * 800,
    77→        outputReservation: 4_000,
    78→      },
    79→    };
    80→  }
    81→}
    82→

