     6→export const countTokensSchema = {
     7→  text: z.string().optional().describe('Text to count tokens in'),
     8→  file: z.string().optional().describe('Absolute or relative file path to read and count'),
     9→  model: z.string().optional().describe(`Claude model ID (default: ${DEFAULT_MODEL_ID})`),
