    11→
    12→export async function countTokens(
    13→  input: { text?: string; file?: string; model?: string },
    14→  tokenizer: TokenizerService,
    15→): Promise<string> {
    16→  const { text, file, model: modelId } = input;
    17→
    18→  if (!text && !file) {
    19→    return 'Error: provide either `text` or `file`.';
    20→  }
    21→
    22→  const model = getModel(modelId ?? DEFAULT_MODEL_ID);
    23→  let content: string;
    24→  let source: string;
