     3→import { BudgetEstimator } from '../core/budgetEstimator.js';
     4→import { getModel, DEFAULT_MODEL_ID } from '../core/modelProfiles.js';
     5→
     6→export const estimateBudgetSchema = {
     7→  files: z.array(z.string()).describe('List of file paths to include in the budget'),
     8→  model: z.string().optional().describe(`Claude model ID (default: ${DEFAULT_MODEL_ID})`),
     9→  chat_turns: z.number().int().min(0).optional().describe('Number of chat turns so far (default: 0)'),
    10→  instruction_files: z.number().int().min(0).optional().describe('Number of instruction files attached (default: 0)'),
    11→};
    12→
    13→export async function estimateBudget(
    14→  input: { files: string[]; model?: string; chat_turns?: number; instruction_files?: number },
    15→  tokenizer: TokenizerService,
    16→): Promise<string> {
    17→  const model = getModel(input.model ?? DEFAULT_MODEL_ID);
    18→  const chatTurns = input.chat_turns ?? 0;
    19→  const instructionFiles = input.instruction_files ?? 0;
    20→
    21→  const estimator = new BudgetEstimator(tokenizer);
    22→  const fileBudgets = estimator.countAllFiles(input.files);
    23→  const budget = estimator.computeBudget(fileBudgets, chatTurns, instructionFiles, model.contextWindow);
    24→
    25→  const fmtK = (n: number) => n >= 1000 ? `${(n / 1000).toFixed(1)}K` : String(n);
    26→  const pct = (n: number) => `${((n / model.contextWindow) * 100).toFixed(1)}%`;
    27→
    28→  const errors = fileBudgets.filter(f => f.error);
    29→
    30→  const lines: string[] = [
    31→    `Model:    ${model.label} (${fmtK(model.contextWindow)} ctx)`,
    32→    `Budget:   ${fmtK(budget.used)} / ${fmtK(budget.capacity)} (${budget.percent.toFixed(1)}%) — ${budget.budgetLevel.toUpperCase()}`,
    33→    '',
    34→    'Breakdown:',
    35→    `  Files:          ~${fmtK(budget.breakdown.files).padStart(8)}  ${pct(budget.breakdown.files)}`,
    36→    `  System prompt:  ~${fmtK(budget.breakdown.systemPrompt).padStart(8)}  ${pct(budget.breakdown.systemPrompt)}`,
    37→    `  Instructions:   ~${fmtK(budget.breakdown.instructions).padStart(8)}  ${pct(budget.breakdown.instructions)}`,
    38→    `  Conversation:   ~${fmtK(budget.breakdown.conversation).padStart(8)}  ${pct(budget.breakdown.conversation)}`,
    39→    `  Output reserve: ~${fmtK(budget.breakdown.outputReservation).padStart(8)}  ${pct(budget.breakdown.outputReservation)}`,
    40→    '',
    41→    'Files:',
    42→    ...fileBudgets.map(f =>
    43→      `  ${f.error ? '[ERR]' : `~${fmtK(f.tokens).padStart(6)}`}  ${f.path}`
    44→    ),
    45→  ];
    46→
    47→  if (errors.length > 0) {
    48→    lines.push('', 'Errors:');
    49→    errors.forEach(f => lines.push(`  ${f.path}: ${f.error}`));
    50→  }
    51→
    52→  const rotWarning = model.rotThreshold;
    53→  if (chatTurns >= rotWarning) {
    54→    lines.push('', `Warning: ${chatTurns} turns >= rot threshold (${rotWarning}) — context may be stale`);
    55→  }
    56→
    57→  return lines.join('\n');
    58→}
