     4→export const previewTurnSchema = {
     5→  current_tokens: z.number().int().min(0).describe('Current estimated token usage'),
     6→  model: z.string().optional().describe(`Claude model ID (default: ${DEFAULT_MODEL_ID})`),
     7→};
     8→
     9→export function previewTurn(input: { current_tokens: number; model?: string }): string {
    10→  const model = getModel(input.model ?? DEFAULT_MODEL_ID);
    11→  const perTurnCost = 800; // estimated tokens per turn (user message + assistant response)
    12→
    13→  const currentInput = input.current_tokens;
    14→  const nextTurnEstimate = currentInput + perTurnCost;
    15→  const percentAfterTurn = Math.min((nextTurnEstimate / model.contextWindow) * 100, 100);
    16→  const remaining = Math.max(model.contextWindow - nextTurnEstimate - model.maxOutput, 0);
    17→  const turnsLeft = Math.floor(remaining / perTurnCost);
    18→
    19→  const fmtK = (n: number) => n >= 1000 ? `${(n / 1000).toFixed(1)}K` : String(n);
    20→
    21→  const barLen = 24;
    22→  const nowFilled = Math.round((currentInput / model.contextWindow) * barLen);
    23→  const nextFilled = Math.round((percentAfterTurn / 100) * barLen);
    24→  const nowBar = '█'.repeat(nowFilled) + '░'.repeat(barLen - nowFilled);
    25→  const nextBar = '█'.repeat(nextFilled) + '░'.repeat(barLen - nextFilled);
    26→
    27→  let warning: string | null = null;
    28→  if (percentAfterTurn >= 90) {
    29→    warning = 'High risk of context overflow on next turn';
    30→  } else if (percentAfterTurn >= 75) {
    31→    warning = 'Approaching context limit — consider compacting';
    32→  }
    33→
    34→  const lines: string[] = [
    35→    `Model:            ${model.label}`,
    36→    `Window:           ${fmtK(model.contextWindow)}`,
    37→    '',
    38→    `Now:              ~${fmtK(currentInput)}  [${nowBar}]`,
    39→    `After next turn:  ~${fmtK(nextTurnEstimate)}  [${nextBar}] (${percentAfterTurn.toFixed(1)}%)`,
    40→    `Turn cost:        +~${fmtK(perTurnCost)}`,
    41→    `Output reserve:   ~${fmtK(model.maxOutput)}`,
    42→    `Remaining:        ~${fmtK(remaining)}  (~${turnsLeft} turns left)`,
    43→  ];
    44→
    45→  if (warning) {
    46→    lines.push('', `Warning: ${warning}`);
    47→  }
    48→
    49→  return lines.join('\n');
    50→}
