     1→import * as vscode from 'vscode';
     2→import { TabInfo } from './types';
     3→
     4→/**
     5→ * Scores each open tab by relevance to the currently active file.
     6→ *
     7→ * Scoring factors:
     8→ *  - Same language as active file       (+0.25)
     9→ *  - Import/export relationship         (+0.30)
    10→ *  - Path similarity (shared dirs)      (+0.20)
    11→ *  - Recently edited                    (+0.15)
    12→ *  - Has diagnostics (errors)           (+0.10)
    13→ */
    14→export class TabRelevanceScorer {
    15→
    16→  /**
    17→   * Score all tabs relative to the active editor.
    18→   */
    19→  scoreAll(
    20→    tabs: TabInfo[],
    21→    activeEditor: vscode.TextEditor | undefined
    22→  ): TabInfo[] {
    23→    if (!activeEditor) {
    24→      return tabs.map(t => ({ ...t, relevanceScore: 0.5, relevanceReason: 'No active editor' }));
    25→    }
    26→
    27→    const activeDoc = activeEditor.document;
    28→    const activeImports = this.extractImports(activeDoc);
    29→    const activePath = activeDoc.uri.fsPath;
    30→    const activeLang = activeDoc.languageId;
    31→    const now = Date.now();
    32→
    33→    return tabs.map(tab => {
    34→      let score = 0;
    35→      const reasons: string[] = [];
    36→
    37→      // 1. Same language
    38→      if (tab.languageId === activeLang) {
    39→        score += 0.25;
    40→        reasons.push('same language');
    41→      }
    42→
    43→      // 2. Import relationship — check if active file imports this tab
    44→      const isImported = this.matchesImport(tab, activeImports);
    45→      if (isImported) {
    46→        score += 0.30;
    47→        reasons.push('imported by active file');
    48→      }
    49→
    50→      // 3. Path similarity — shared directory segments
    51→      const pathScore = this.computePathSimilarity(activePath, tab.uri.fsPath);
    52→      score += pathScore * 0.20;
    53→      if (pathScore > 0.5) {
    54→        reasons.push('nearby path');
    55→      }
    56→
    57→      // 4. Recency of edit
    58→      const ageMs = now - tab.lastEditTimestamp;
    59→      const ageMinutes = ageMs / 60000;
    60→      if (ageMinutes < 2) {
    61→        score += 0.15;
    62→        reasons.push('recently edited');
    63→      } else if (ageMinutes < 10) {
    64→        score += 0.08;
    65→        reasons.push('edited recently');
    66→      }
    67→
    68→      // 5. Diagnostics — files with errors are relevant (you're debugging)
    69→      if (tab.diagnosticCount > 0) {
    70→        score += 0.10;
    71→        reasons.push(`${tab.diagnosticCount} diagnostics`);
    72→      }
    73→
    74→      // 6. Pinned — always maximum relevance
    75→      if (tab.isPinned) {
    76→        score = 1.0;
    77→        reasons.length = 0;
    78→        reasons.push('📌 pinned');
    79→      }
    80→
    81→      // 7. Active file — always maximum
    82→      if (tab.isActive) {
    83→        score = 1.0;
    84→        reasons.length = 0;
    85→        reasons.push('active editor');
    86→      }
    87→
    88→      return {
    89→        ...tab,
    90→        relevanceScore: Math.min(score, 1.0),
    91→        relevanceReason: reasons.join(', ') || 'low relevance',
    92→      };
    93→    });
    94→  }
    95→
    96→  /**
    97→   * Extract import paths from a document (works for TS/JS/Python/Go/Java/etc.)
    98→   */
    99→  private extractImports(doc: vscode.TextDocument): string[] {
   100→    const text = doc.getText();
   101→    const imports: string[] = [];
   102→
   103→    // TypeScript / JavaScript: import ... from '...' or require('...')
   104→    const tsImports = text.matchAll(/(?:import\s+.*?from\s+['"](.+?)['"]|require\s*\(\s*['"](.+?)['"]\s*\))/g);
   105→    for (const match of tsImports) {
   106→      imports.push(match[1] || match[2]);
   107→    }
   108→
   109→    // Python: import X / from X import Y
   110→    const pyImports = text.matchAll(/(?:from\s+([\w.]+)\s+import|import\s+([\w.]+))/g);
   111→    for (const match of pyImports) {
   112→      imports.push((match[1] || match[2]).replace(/\./g, '/'));
   113→    }
   114→
   115→    // Go: import "path"
   116→    const goImports = text.matchAll(/import\s+(?:\w+\s+)?"(.+?)"/g);
   117→    for (const match of goImports) {
   118→      imports.push(match[1]);
   119→    }
   120→
   121→    // Java: import package.Class
   122→    const javaImports = text.matchAll(/import\s+([\w.]+);/g);
   123→    for (const match of javaImports) {
   124→      imports.push(match[1].replace(/\./g, '/'));
   125→    }
   126→
   127→    return imports;
   128→  }
   129→
   130→  /**
   131→   * Check if a tab matches any of the imports from the active file.
   132→   * More precise than simple .includes() — handles relative paths properly.
   133→   */
   134→  private matchesImport(tab: TabInfo, imports: string[]): boolean {
   135→    const tabName = this.fileNameNoExt(tab.relativePath);
   136→    const tabPath = tab.relativePath.replace(/\\/g, '/');
   137→
   138→    for (const imp of imports) {
   139→      // Normalize the import path
   140→      const normalizedImport = imp.replace(/\\/g, '/').replace(/^\.\//, '');
   141→
   142→      // Direct match: import ends with the tab's filename (without extension)
   143→      // e.g., import './utils' matches 'src/utils.ts'
   144→      if (normalizedImport.endsWith(tabName)) {
   145→        // Verify it's not a partial match (e.g., 'utils' shouldn't match 'old-utils')
   146→        const beforeName = normalizedImport.slice(0, -tabName.length);
   147→        if (beforeName === '' || beforeName.endsWith('/')) {
   148→          return true;
   149→        }
   150→      }
   151→
   152→      // Path suffix match: tab path ends with the import path
   153→      // e.g., import '../core/types' matches 'src/core/types.ts'
   154→      const importWithoutExt = normalizedImport.replace(/\.[^/.]+$/, '');
   155→      const tabWithoutExt = tabPath.replace(/\.[^/.]+$/, '');
   156→      if (tabWithoutExt.endsWith(importWithoutExt)) {
   157→        const beforeMatch = tabWithoutExt.slice(0, -importWithoutExt.length);
   158→        if (beforeMatch === '' || beforeMatch.endsWith('/')) {
   159→          return true;
   160→        }
   161→      }
   162→    }
   163→
   164→    return false;
   165→  }
   166→
   167→  /**
   168→   * Compute path similarity based on shared directory.
   169→   * Files in the same directory score highest, nearby directories score lower.
   170→   */
   171→  private computePathSimilarity(pathA: string, pathB: string): number {
   172→    const normA = pathA.replace(/\\/g, '/');
   173→    const normB = pathB.replace(/\\/g, '/');
   174→    const dirA = normA.split('/').slice(0, -1); // Remove filename
   175→    const dirB = normB.split('/').slice(0, -1);
   176→
   177→    if (dirA.length === 0 || dirB.length === 0) { return 0; }
   178→
   179→    // Count shared prefix segments
   180→    let shared = 0;
   181→    for (let i = 0; i < Math.min(dirA.length, dirB.length); i++) {
   182→      if (dirA[i] === dirB[i]) { shared++; } else { break; }
   183→    }
   184→
   185→    // Same directory = 1.0, each level apart reduces score
   186→    const maxDepth = Math.max(dirA.length, dirB.length);
   187→    if (shared === dirA.length && shared === dirB.length) {
   188→      return 1.0; // Same directory
   189→    }
   190→
   191→    // Score based on how much of the path is shared
   192→    return shared / maxDepth;
   193→  }
   194→
   195→  private fileNameNoExt(filePath: string): string {
   196→    const base = filePath.split('/').pop() || '';
   197→    return base.replace(/\.[^.]+$/, '');
   198→  }
   199→}
