   314→  /**
   315→   * /compaction — Per-turn token growth and compaction recommendations
   316→   */
   317→  private async handleCompaction(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   318→    await this.monitor.refresh();
   319→    const snapshot = this.monitor.getLatestSnapshot();
   320→
   321→    if (!snapshot) {
   322→      stream.markdown('Unable to get compaction data.');
   323→      return {};
   324→    }
   325→
   326→    const model = this.monitor.getActiveModel();
   327→    const history = snapshot.turnHistory;
   328→    const breakdown = snapshot.budgetBreakdown;
   329→
   330→    stream.markdown(`## Context Growth\n\n`);
   331→
   332→    // Current budget breakdown
   333→    stream.markdown(`### Budget Breakdown\n\n`);
   334→    stream.markdown(`| Category | Tokens | % of Window |\n|---|---|---|\n`);
   335→    const entries: [string, number][] = [
   336→      ['Files', breakdown.files],
   337→      ['System prompt', breakdown.systemPrompt],
   338→      ['Instructions', breakdown.instructions],
   339→      ['Conversation', breakdown.conversation],
   340→      ['Output reserve', breakdown.outputReservation],
   341→    ];
   342→    for (const [label, tokens] of entries) {
   343→      const pct = ((tokens / snapshot.windowCapacity) * 100).toFixed(1);
   344→      stream.markdown(`| ${label} | ~${this.fmtTokens(tokens)} | ${pct}% |\n`);
   345→    }
   346→    stream.markdown(`| **Total** | **~${this.fmtTokens(snapshot.totalEstimatedTokens)}** | **${snapshot.usagePercent.toFixed(1)}%** |\n\n`);
   347→
   348→    // Per-turn history table
   349→    if (history.length > 0) {
   350→      stream.markdown(`### Turn History\n\n`);
   351→      stream.markdown(`| Turn | Input | Files | Overhead | Tabs | Pinned |\n|---|---|---|---|---|---|\n`);
   352→
   353→      for (const t of history) {
   354→        stream.markdown(`| ${t.turn} | ~${this.fmtTokens(t.inputTokens)} | ~${this.fmtTokens(t.fileTokens)} | ~${this.fmtTokens(t.overheadTokens)} | ${t.tabCount} | ${t.pinnedCount} |\n`);
   355→      }
   356→
   357→      // Growth analysis
   358→      stream.markdown(`\n### Growth Analysis\n\n`);
   359→
   360→      const avgGrowth = history.length >= 2
   361→        ? (history[history.length - 1].inputTokens - history[0].inputTokens) / (history.length - 1)
   362→        : 0;
   363→
   364→      const firstFile = history[0].fileTokens;
   365→      const lastFile = history[history.length - 1].fileTokens;
   366→      const fileTrend = lastFile > firstFile * 1.1 ? 'growing' : lastFile < firstFile * 0.9 ? 'shrinking' : 'stable';
   367→
   368→      stream.markdown(`- **Conversation cost:** ~800 tokens/turn (estimated)\n`);
   369→      if (history.length >= 2) {
   370→        stream.markdown(`- **Input growth rate:** ~${this.fmtTokens(Math.round(avgGrowth))}/turn\n`);
   371→      }
   372→      stream.markdown(`- **File tokens:** ${fileTrend} (${this.fmtTokens(firstFile)} → ${this.fmtTokens(lastFile)})\n`);
   373→      stream.markdown(`- **Output reserved:** ~${this.fmtTokens(model.maxOutput)} per response\n\n`);
   374→    } else {
   375→      stream.markdown(`*No turn history yet.* Use \`@tokalator /pin\`, \`/optimize\`, or \`/unpin\` to start tracking.\n\n`);
   376→    }
   377→
   378→    // Actionable suggestions
   379→    const suggestions: string[] = [];
   380→
   381→    const config = vscode.workspace.getConfiguration('tokalator');
   382→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   383→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   384→    if (distractors.length > 0) {
   385→      const saveable = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
   386→      suggestions.push(`Close ${distractors.length} low-relevance tabs to save ~${this.fmtTokens(saveable)} tokens`);
   387→    }
   388→
   389→    const turnsLeft = model.rotThreshold - snapshot.chatTurnCount;
   390→    if (turnsLeft <= 5 && turnsLeft > 0) {
   391→      suggestions.push(`${turnsLeft} turns until context rot threshold (${model.rotThreshold}) — consider \`/reset\``);
   392→    } else if (turnsLeft <= 0) {
   393→      suggestions.push(`Past context rot threshold (${model.rotThreshold} turns) — run \`/reset\` to clear`);
   394→    }
   395→
   396→    const inputPct = snapshot.usagePercent;
   397→    if (inputPct >= 80) {
   398→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — compaction point reached`);
   399→    } else if (inputPct >= 60) {
   400→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — approaching compaction point`);
   401→    }
   402→
   403→    const pinnedCount = snapshot.pinnedFiles.size;
   404→    if (pinnedCount > 5) {
   405→      suggestions.push(`${pinnedCount} files pinned — unpin files you're done with`);
   406→    }
   407→
   408→    if (suggestions.length > 0) {
   409→      stream.markdown(`### Recommendations\n\n`);
   410→      for (const s of suggestions) {
   411→        stream.markdown(`- ${s}\n`);
   412→      }
   413→    } else {
   414→      stream.markdown(`> Context looks healthy — no compaction needed yet.\n`);
   415→    }
   416→
   417→    return {};
   418→  }
