   496→        : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';
   497→      stream.markdown(`**Current:** ${levelEmoji} ${snapshot.tabs.length} tabs, budget ${snapshot.budgetLevel}\n`);
