   501→  }
   502→
   503→  /**
   504→   * /instructions — List instruction files and their token cost
   505→   */
   506→  private async handleInstructions(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   507→    stream.progress('Scanning instruction files...');
   508→
   509→    // Find all instruction-like files
   510→    const patterns = [
   511→      '**/*.instructions.md',
   512→      '**/.github/copilot-instructions.md',
   513→      '**/.copilot/*.md',
   514→      '**/*.prompt.md',
   515→      '**/.cursorrules',
   516→      '**/.claude/**/*.md',
   517→      '**/CLAUDE.md',
   518→      '**/AGENTS.md',
   519→      '**/*.agent.md',
   520→    ];
   521→
   522→    const allFiles: { path: string; tokens: number }[] = [];
   523→
   524→    for (const pattern of patterns) {
   525→      try {
   526→        const files = await vscode.workspace.findFiles(pattern, '**/node_modules/**', 50);
   527→        for (const uri of files) {
   528→          try {
   529→            const doc = await vscode.workspace.openTextDocument(uri);
   530→            const model = this.monitor.getActiveModel();
   531→            const tokenizer = this.monitor.getTokenizer();
   532→            const tokens = tokenizer.countTokens(doc.getText(), model.provider);
   533→            allFiles.push({
   534→              path: vscode.workspace.asRelativePath(uri),
   535→              tokens,
   536→            });
   537→          } catch {
   538→            allFiles.push({ path: vscode.workspace.asRelativePath(uri), tokens: 0 });
   539→          }
   540→        }
   541→      } catch {
   542→        // pattern not found
   543→      }
   544→    }
   545→
   546→    if (allFiles.length === 0) {
   547→      stream.markdown('No instruction files found in this workspace.\n\n');
   548→      stream.markdown('Instruction files are automatically attached to AI context. Common patterns:\n\n');
   549→      stream.markdown('| File | Used by |\n|---|---|\n');
   550→      stream.markdown('| `.github/copilot-instructions.md` | GitHub Copilot |\n');
   551→      stream.markdown('| `*.instructions.md` | GitHub Copilot |\n');
   552→      stream.markdown('| `*.prompt.md` | Copilot / Claude |\n');
   553→      stream.markdown('| `AGENTS.md` | Claude Code |\n');
   554→      stream.markdown('| `.cursorrules` | Cursor |\n');
   555→      return {};
   556→    }
   557→
   558→    // Sort by tokens descending
   559→    allFiles.sort((a, b) => b.tokens - a.tokens);
   560→    const totalTokens = allFiles.reduce((sum, f) => sum + f.tokens, 0);
   561→
   562→    stream.markdown(`## Instruction Files\n\n`);
   563→    stream.markdown(`**${allFiles.length} files** using ~${this.fmtTokens(totalTokens)} tokens\n\n`);
   564→    stream.markdown(`| File | Tokens |\n|---|---|\n`);
   565→
   566→    for (const f of allFiles) {
   567→      stream.markdown(`| \`${f.path}\` | ~${this.fmtTokens(f.tokens)} |\n`);
   568→    }
   569→
   570→    const model = this.monitor.getActiveModel();
   571→    const pct = ((totalTokens / model.contextWindow) * 100).toFixed(1);
   572→    stream.markdown(`\n> Instructions use **${pct}%** of ${model.label}'s ${this.fmtTokens(model.contextWindow)} context window\n`);
   573→
   574→    return {};
   575→  }
   576→
   577→  /**
   578→   * /model — Show or switch the active model
   579→   */
   580→  private async handleModel(
   581→    request: vscode.ChatRequest,
   582→    stream: vscode.ChatResponseStream,
   583→  ): Promise<vscode.ChatResult> {
   584→    const query = request.prompt.trim();
   585→    const currentModel = this.monitor.getActiveModel();
   586→
   587→    if (!query) {
   588→      // Show current model and list all
   589→      stream.markdown(`## Active Model: ${currentModel.label}\n\n`);
   590→      stream.markdown(`| | |\n|---|---|\n`);
   591→      const tokenizer = this.monitor.getTokenizer();
   592→      stream.markdown(`| **Context window** | ${this.fmtTokens(currentModel.contextWindow)} |\n`);
   593→      stream.markdown(`| **Max output** | ${this.fmtTokens(currentModel.maxOutput)} |\n`);
   594→      stream.markdown(`| **Tokenizer** | ${tokenizer.getTokenizerLabel(currentModel.provider)} |\n`);
   595→      stream.markdown(`| **Rot threshold** | ${currentModel.rotThreshold} turns |\n`);
   596→      stream.markdown(`| **Provider** | ${currentModel.provider} |\n\n`);
   597→
   598→      stream.markdown(`### Available Models\n\n`);
   599→      const models = this.monitor.getModels();
   600→      for (const m of models) {
   601→        const active = m.id === currentModel.id ? ' ← active' : '';
   602→        stream.markdown(`- **${m.label}** — ${this.fmtTokens(m.contextWindow)}${active}\n`);
   603→      }
   604→      stream.markdown(`\nSwitch with: \`@tokalator /model claude sonnet 4.5\`\n`);
   605→      return {};
   606→    }
   607→
   608→    // Try to find matching model
   609→    const match = findModel(query);
   610→
   611→    if (!match) {
   612→      stream.markdown(`No model matching "${query}". Try \`@tokalator /model\` to see all options.\n`);
   613→      return {};
   614→    }
   615→
   616→    this.monitor.setModel(match.id);
   617→    stream.markdown(`Switched to **${match.label}**\n\n`);
   618→    stream.markdown(`| | |\n|---|---|\n`);
   619→    stream.markdown(`| **Context window** | ${this.fmtTokens(match.contextWindow)} |\n`);
   620→    stream.markdown(`| **Max output** | ${this.fmtTokens(match.maxOutput)} |\n`);
   621→    stream.markdown(`| **Rot threshold** | ${match.rotThreshold} turns |\n`);
   622→
   623→    return {};
   624→  }
   625→
   626→  private fmtTokens(n: number): string {
   627→    return n >= 1000 ? (n / 1000).toFixed(1) + 'K' : n.toString();
   628→  }
   629→
   630→  private relevanceLabel(score: number): string {
   631→    if (score >= 0.6) { return 'high'; }
   632→    if (score >= 0.3) { return 'med'; }
   633→    return 'low';
   634→  }
   635→
   636→  private stripQuotes(value: string): string {
   637→    if (value.length >= 2) {
   638→      const first = value[0];
   639→      const last = value[value.length - 1];
   640→      if (first === last && ['"', "'", '`'].includes(first)) {
   641→        return value.slice(1, -1);
   642→      }
   643→    }
   644→    return value;
   645→  }
   646→
   647→  private async resolveUrisFromInput(input: string): Promise<vscode.Uri[]> {
   648→    const normalized = this.normalizeInputPath(input);
   649→    if (!normalized) { return []; }
   650→
   651→    if (this.isAbsolutePath(normalized)) {
   652→      const absoluteUri = vscode.Uri.file(normalized);
   653→      if (await this.fileExists(absoluteUri)) {
   654→        return [absoluteUri];
   655→      }
   656→    }
   657→
   658→    const relativeUri = await this.tryResolveRelative(normalized);
   659→    if (relativeUri) {
   660→      return [relativeUri];
   661→    }
   662→
   663→    return this.searchWorkspace(normalized);
   664→  }
   665→
   666→  private normalizeInputPath(value: string): string {
   667→    if (!value) { return ''; }
   668→    const expanded = value.startsWith('~')
   669→      ? path.join(os.homedir(), value.slice(1))
   670→      : value;
   671→    return path.normalize(expanded);
   672→  }
   673→
   674→  private isAbsolutePath(p: string): boolean {
   675→    return path.isAbsolute(p) || /^[A-Za-z]:[\\/]/.test(p);
   676→  }
   677→
   678→  private async tryResolveRelative(relativePath: string): Promise<vscode.Uri | null> {
   679→    const trimmed = relativePath.replace(/^(\.\\|\.\/)+/, '').replace(/^\\+|^\/+/, '');
   680→    if (!trimmed) { return null; }
   681→    const folders = vscode.workspace.workspaceFolders || [];
   682→    for (const folder of folders) {
   683→      const candidate = vscode.Uri.file(path.join(folder.uri.fsPath, trimmed));
   684→      if (await this.fileExists(candidate)) {
   685→        return candidate;
   686→      }
   687→    }
   688→    return null;
   689→  }
   690→
   691→  private async searchWorkspace(target: string): Promise<vscode.Uri[]> {
   692→    const globTarget = target.replace(/^[/\\]+/, '').replace(/\\/g, '/');
   693→    if (!globTarget) { return []; }
   694→    try {
   695→      return await vscode.workspace.findFiles(`**/${globTarget}`, '**/node_modules/**', 5);
   696→    } catch {
   697→      return [];
   698→    }
   699→  }
   700→
   701→  private async fileExists(uri: vscode.Uri): Promise<boolean> {
   702→    try {
   703→      const stat = await vscode.workspace.fs.stat(uri);
   704→      return stat.type === vscode.FileType.File;
   705→    } catch {
   706→      return false;
   707→    }
   708→  }
   709→
   710→  private dedupeUris(uris: vscode.Uri[]): vscode.Uri[] {
   711→    const seen = new Set<string>();
   712→    const unique: vscode.Uri[] = [];
   713→    for (const uri of uris) {
   714→      const key = uri.toString();
   715→      if (!seen.has(key)) {
   716→        seen.add(key);
   717→        unique.push(uri);
   718→      }
   719→    }
   720→    return unique;
   721→  }
   722→
   723→  /**
   724→   * Auto-detect the model from the Copilot chat request and sync Tokalator to it.
   725→   * Tries to match by family → id → name so switching models in the Copilot UI
   726→   * automatically updates context window and tokenizer without any manual step.
   727→   */
   728→  private async syncModelFromRequest(request: vscode.ChatRequest): Promise<void> {
   729→    const lm = request.model;
   730→    if (!lm) { return; }
   731→
   732→    const current = this.monitor.getActiveModel();
   733→    // Try family first (most stable identifier), then full id, then display name
   734→    const match = findModel(lm.family) ?? findModel(lm.id) ?? findModel(lm.name);
   735→
   736→    if (match && match.id !== current.id) {
   737→      await this.monitor.setModel(match.id);
   738→    }
   739→  }
   740→
   741→  dispose(): void {
   742→    this.participant.dispose();
   743→  }
   744→}
