     1→/**
     2→ * Multi-turn Conversation Cost Estimator
     3→ * Simulate conversation costs with different context management strategies
     4→ */
     5→
     6→import { calculateCost, formatCost, MODEL_LIMITS } from './pricing';
     7→
     8→// ============================================
     9→// TYPES
    10→// ============================================
    11→
    12→export type ContextStrategy = 'full' | 'sliding-window' | 'summarize';
    13→
    14→export interface ConversationParams {
    15→  systemPromptTokens: number;
    16→  avgUserTokens: number;
    17→  avgAssistantTokens: number;
    18→  turns: number;
    19→  model: string;
    20→  strategy: ContextStrategy;
    21→  windowSize?: number; // For sliding window: number of turns to keep
    22→  compressionRatio?: number; // For summarize: how much to compress (0.1 = 10% of original)
    23→}
    24→
    25→export interface TurnBreakdown {
    26→  turn: number;
    27→  inputTokens: number;
    28→  outputTokens: number;
    29→  contextSize: number;
    30→  turnCost: number;
    31→  cumulativeCost: number;
    32→}
    33→
    34→export interface ConversationAnalysis {
    35→  turnBreakdown: TurnBreakdown[];
    36→  totalCost: number;
    37→  totalInputTokens: number;
    38→  totalOutputTokens: number;
    39→  avgCostPerTurn: number;
    40→  finalContextSize: number;
    41→  peakContextSize: number;
    42→  exceedsLimit: boolean;
    43→  limitExceededAtTurn: number | null;
    44→}
    45→
    46→export interface StrategyComparison {
    47→  full: ConversationAnalysis;
    48→  slidingWindow: ConversationAnalysis;
    49→  summarize: ConversationAnalysis;
    50→}
    51→
    52→// ============================================
    53→// CONVERSATION SIMULATION
    54→// ============================================
    55→
    56→/**
    57→ * Simulate a multi-turn conversation
    58→ */
    59→export function simulateConversation(params: ConversationParams): ConversationAnalysis {
    60→  const {
    61→    systemPromptTokens,
    62→    avgUserTokens,
    63→    avgAssistantTokens,
    64→    turns,
    65→    model,
    66→    strategy,
    67→    windowSize = 5,
    68→    compressionRatio = 0.2,
    69→  } = params;
    70→
    71→  const limits = MODEL_LIMITS[model as keyof typeof MODEL_LIMITS];
    72→  const contextLimit = limits?.contextWindow || 200_000;
    73→
    74→  const turnBreakdown: TurnBreakdown[] = [];
    75→  let cumulativeCost = 0;
    76→  const messageHistory: Array<{ role: 'user' | 'assistant'; tokens: number }> = [];
    77→  let summarizedTokens = 0;
    78→  let exceedsLimit = false;
    79→  let limitExceededAtTurn: number | null = null;
    80→  let peakContextSize = 0;
    81→
    82→  for (let turn = 1; turn <= turns; turn++) {
    83→    // Add user message
    84→    messageHistory.push({ role: 'user', tokens: avgUserTokens });
    85→
    86→    // Calculate context size based on strategy
    87→    let contextSize: number;
    88→
    89→    switch (strategy) {
    90→      case 'full':
    91→        // Full context: system + all messages
    92→        contextSize = systemPromptTokens +
    93→          messageHistory.reduce((sum, msg) => sum + msg.tokens, 0);
    94→        break;
    95→
    96→      case 'sliding-window':
    97→        // Keep only last N turns (N * 2 messages for user+assistant pairs)
    98→        const windowMessages = windowSize * 2;
    99→        const recentMessages = messageHistory.slice(-windowMessages);
   100→        contextSize = systemPromptTokens +
   101→          recentMessages.reduce((sum, msg) => sum + msg.tokens, 0);
   102→        break;
   103→
   104→      case 'summarize':
   105→        // Compress older messages, keep recent ones fresh
   106→        const recentTurns = 2; // Keep last 2 turns uncompressed
   107→        const recentCount = recentTurns * 2;
   108→
   109→        if (messageHistory.length > recentCount) {
   110→          const oldMessages = messageHistory.slice(0, -recentCount);
   111→          const oldTokens = oldMessages.reduce((sum, msg) => sum + msg.tokens, 0);
   112→          summarizedTokens = Math.ceil(oldTokens * compressionRatio);
   113→        }
   114→
   115→        const freshMessages = messageHistory.slice(-recentCount);
   116→        const freshTokens = freshMessages.reduce((sum, msg) => sum + msg.tokens, 0);
   117→        contextSize = systemPromptTokens + summarizedTokens + freshTokens;
   118→        break;
   119→
   120→      default:
   121→        contextSize = systemPromptTokens;
   122→    }
   123→
   124→    // Input tokens = context size (what we send to the model)
   125→    const inputTokens = contextSize;
   126→    const outputTokens = avgAssistantTokens;
   127→
   128→    // Check if we exceed the limit
   129→    if (contextSize > contextLimit && !exceedsLimit) {
   130→      exceedsLimit = true;
   131→      limitExceededAtTurn = turn;
   132→    }
   133→
   134→    peakContextSize = Math.max(peakContextSize, contextSize);
   135→
   136→    // Calculate cost for this turn
   137→    const cost = calculateCost(model, { inputTokens, outputTokens });
   138→    cumulativeCost += cost.totalCost;
   139→
   140→    turnBreakdown.push({
   141→      turn,
   142→      inputTokens,
   143→      outputTokens,
   144→      contextSize,
   145→      turnCost: cost.totalCost,
   146→      cumulativeCost,
   147→    });
   148→
   149→    // Add assistant response to history
   150→    messageHistory.push({ role: 'assistant', tokens: avgAssistantTokens });
   151→  }
   152→
   153→  const totalInputTokens = turnBreakdown.reduce((sum, t) => sum + t.inputTokens, 0);
   154→  const totalOutputTokens = turnBreakdown.reduce((sum, t) => sum + t.outputTokens, 0);
   155→
   156→  return {
   157→    turnBreakdown,
   158→    totalCost: cumulativeCost,
   159→    totalInputTokens,
   160→    totalOutputTokens,
   161→    avgCostPerTurn: cumulativeCost / turns,
   162→    finalContextSize: turnBreakdown[turnBreakdown.length - 1]?.contextSize || 0,
   163→    peakContextSize,
   164→    exceedsLimit,
   165→    limitExceededAtTurn,
   166→  };
   167→}
   168→
   169→/**
   170→ * Compare all strategies side by side
   171→ */
   172→export function compareStrategies(
   173→  baseParams: Omit<ConversationParams, 'strategy'>,
   174→  windowSize: number = 5,
   175→  compressionRatio: number = 0.2
   176→): StrategyComparison {
   177→  return {
   178→    full: simulateConversation({ ...baseParams, strategy: 'full' }),
   179→    slidingWindow: simulateConversation({
   180→      ...baseParams,
   181→      strategy: 'sliding-window',
   182→      windowSize
   183→    }),
   184→    summarize: simulateConversation({
   185→      ...baseParams,
   186→      strategy: 'summarize',
   187→      compressionRatio
   188→    }),
   189→  };
   190→}
   191→
   192→/**
   193→ * Get strategy description
   194→ */
   195→export function getStrategyDescription(strategy: ContextStrategy): {
   196→  name: string;
   197→  description: string;
   198→  pros: string[];
   199→  cons: string[];
   200→} {
   201→  switch (strategy) {
   202→    case 'full':
   203→      return {
   204→        name: 'Full Context',
   205→        description: 'Keep entire conversation history in context',
   206→        pros: ['Best coherence', 'No information loss', 'Simple to implement'],
   207→        cons: ['Cost grows quadratically', 'May hit context limits', 'Slowest responses'],
   208→      };
   209→    case 'sliding-window':
   210→      return {
   211→        name: 'Sliding Window',
   212→        description: 'Keep only the last N turns in context',
   213→        pros: ['Predictable costs', 'Never hits limits', 'Fast responses'],
   214→        cons: ['Loses old context', 'May forget earlier instructions', 'Abrupt cutoff'],
   215→      };
   216→    case 'summarize':
   217→      return {
   218→        name: 'Summarization',
   219→        description: 'Compress older messages, keep recent ones fresh',
   220→        pros: ['Balanced approach', 'Preserves key info', 'Moderate costs'],
   221→        cons: ['Summary quality varies', 'Extra complexity', 'Some information loss'],
   222→      };
   223→  }
   224→}
   225→
   226→/**
   227→ * Calculate optimal turn count for a budget
   228→ */
   229→export function calculateTurnsForBudget(
   230→  budget: number,
   231→  params: Omit<ConversationParams, 'turns'>
   232→): number {
   233→  // Binary search for max turns within budget
   234→  let low = 1;
   235→  let high = 1000;
   236→  let result = 1;
   237→
   238→  while (low <= high) {
   239→    const mid = Math.floor((low + high) / 2);
   240→    const analysis = simulateConversation({ ...params, turns: mid });
   241→
   242→    if (analysis.totalCost <= budget) {
   243→      result = mid;
   244→      low = mid + 1;
   245→    } else {
   246→      high = mid - 1;
   247→    }
   248→  }
   249→
   250→  return result;
   251→}
   252→
   253→/**
   254→ * Format conversation analysis for display
   255→ */
   256→export function formatConversationSummary(analysis: ConversationAnalysis): string {
   257→  return `${analysis.turnBreakdown.length} turns, ${formatCost(analysis.totalCost)} total, ` +
   258→    `${(analysis.finalContextSize / 1000).toFixed(1)}K final context`;
   259→}
