     1→/**
     2→ * Context Window Utilities
     3→ * Helps visualize and optimize context budget usage
     4→ */
     5→
     6→import { MODEL_LIMITS } from './pricing';
     7→
     8→// ============================================
     9→// TYPES
    10→// ============================================
    11→
    12→export interface ContextBudget {
    13→  systemPromptTokens: number;
    14→  userInputTokens: number;
    15→  reservedOutputTokens: number;
    16→  model: string;
    17→}
    18→
    19→export interface ContextAnalysis {
    20→  totalUsed: number;
    21→  totalAvailable: number;
    22→  remaining: number;
    23→  usagePercent: number;
    24→  isOverLimit: boolean;
    25→  isInExtendedPricing: boolean; // For Sonnet >200K
    26→  breakdown: {
    27→    systemPrompt: { tokens: number; percent: number };
    28→    userInput: { tokens: number; percent: number };
    29→    reservedOutput: { tokens: number; percent: number };
    30→    free: { tokens: number; percent: number };
    31→  };
    32→  warnings: string[];
    33→}
    34→
    35→// ============================================
    36→// TOKEN ESTIMATION
    37→// ============================================
    38→
    39→/**
    40→ * Estimate token count from text
    41→ * Uses ~4 characters per token heuristic (reasonably accurate for English)
    42→ */
    43→export function estimateTokens(text: string): number {
    44→  if (!text) return 0;
    45→  // More accurate heuristic: ~4 chars per token for English
    46→  // Accounts for whitespace and punctuation
    47→  return Math.ceil(text.length / 4);
    48→}
    49→
    50→/**
    51→ * Estimate characters from token count
    52→ */
    53→export function estimateCharacters(tokens: number): number {
    54→  return tokens * 4;
    55→}
    56→
    57→// ============================================
    58→// CONTEXT ANALYSIS
    59→// ============================================
    60→
    61→/**
    62→ * Analyze context budget usage
    63→ */
    64→export function analyzeContextBudget(budget: ContextBudget): ContextAnalysis {
    65→  const limits = MODEL_LIMITS[budget.model as keyof typeof MODEL_LIMITS];
    66→
    67→  if (!limits) {
    68→    throw new Error(`Unknown model: ${budget.model}`);
    69→  }
    70→
    71→  const totalUsed = budget.systemPromptTokens + budget.userInputTokens + budget.reservedOutputTokens;
    72→  const totalAvailable = limits.contextWindow;
    73→  const remaining = Math.max(0, totalAvailable - totalUsed);
    74→  const usagePercent = (totalUsed / totalAvailable) * 100;
    75→
    76→  // Check for Sonnet extended pricing threshold
    77→  const isInExtendedPricing = budget.model === 'claude-sonnet-4.5' &&
    78→    (budget.systemPromptTokens + budget.userInputTokens) > 200_000;
    79→
    80→  // Generate warnings
    81→  const warnings: string[] = [];
    82→
    83→  if (usagePercent > 90) {
    84→    warnings.push('Context usage above 90% - consider reducing input size');
    85→  }
    86→
    87→  if (budget.reservedOutputTokens > limits.maxOutput) {
    88→    warnings.push(`Reserved output exceeds model maximum (${limits.maxOutput.toLocaleString()} tokens)`);
    89→  }
    90→
    91→  if (isInExtendedPricing) {
    92→    warnings.push('Extended context pricing applies (>200K tokens) - 2x input cost');
    93→  }
    94→
    95→  if (totalUsed > totalAvailable) {
    96→    warnings.push('Total context exceeds model limit!');
    97→  }
    98→
    99→  return {
   100→    totalUsed,
   101→    totalAvailable,
   102→    remaining,
   103→    usagePercent: Math.min(100, usagePercent),
   104→    isOverLimit: totalUsed > totalAvailable,
   105→    isInExtendedPricing,
   106→    breakdown: {
   107→      systemPrompt: {
   108→        tokens: budget.systemPromptTokens,
   109→        percent: (budget.systemPromptTokens / totalAvailable) * 100,
   110→      },
   111→      userInput: {
   112→        tokens: budget.userInputTokens,
   113→        percent: (budget.userInputTokens / totalAvailable) * 100,
   114→      },
   115→      reservedOutput: {
   116→        tokens: budget.reservedOutputTokens,
   117→        percent: (budget.reservedOutputTokens / totalAvailable) * 100,
   118→      },
   119→      free: {
   120→        tokens: remaining,
   121→        percent: (remaining / totalAvailable) * 100,
   122→      },
   123→    },
   124→    warnings,
   125→  };
   126→}
   127→
   128→/**
   129→ * Calculate how many more turns can fit in context
   130→ */
   131→export function calculateRemainingTurns(
   132→  currentContextTokens: number,
   133→  avgTurnTokens: number,
   134→  model: string
   135→): number {
   136→  const limits = MODEL_LIMITS[model as keyof typeof MODEL_LIMITS];
   137→  if (!limits || avgTurnTokens <= 0) return 0;
   138→
   139→  const remaining = limits.contextWindow - currentContextTokens;
   140→  return Math.floor(remaining / avgTurnTokens);
   141→}
   142→
   143→/**
   144→ * Get model context limits
   145→ */
   146→export function getModelLimits(model: string) {
   147→  return MODEL_LIMITS[model as keyof typeof MODEL_LIMITS] || null;
   148→}
   149→
   150→/**
   151→ * Format token count for display
   152→ */
   153→export function formatTokenCount(tokens: number): string {
   154→  if (tokens >= 1_000_000) {
   155→    return `${(tokens / 1_000_000).toFixed(1)}M`;
   156→  }
   157→  if (tokens >= 1_000) {
   158→    return `${(tokens / 1_000).toFixed(1)}K`;
   159→  }
   160→  return tokens.toLocaleString();
   161→}
