     1→/**
     2→ * Caching ROI Calculator
     3→ * Calculate break-even point and savings for prompt caching
     4→ */
     5→
     6→import { getPricingTier, formatCost } from './pricing';
     7→
     8→// ============================================
     9→// TYPES
    10→// ============================================
    11→
    12→export interface CachingAnalysis {
    13→  cacheWriteCost: number;
    14→  cacheReadCostPerUse: number;
    15→  inputCostPerUse: number;
    16→  savingsPerReuse: number;
    17→  breakEvenReuses: number;
    18→  totalWithCaching: number;
    19→  totalWithoutCaching: number;
    20→  netSavings: number;
    21→  savingsPercent: number;
    22→  shouldCache: boolean;
    23→  recommendation: string;
    24→}
    25→
    26→export interface CachingScenario {
    27→  cacheTokens: number;
    28→  reuseCount: number;
    29→  model: string;
    30→}
    31→
    32→// ============================================
    33→// CACHING CALCULATIONS
    34→// ============================================
    35→
    36→/**
    37→ * Calculate comprehensive caching analysis
    38→ */
    39→export function analyzeCaching(scenario: CachingScenario): CachingAnalysis {
    40→  const { cacheTokens, reuseCount, model } = scenario;
    41→  const pricing = getPricingTier(model);
    42→
    43→  // Costs per million tokens
    44→  const inputCostPerMTok = pricing.inputCostPerMTok;
    45→  const cacheWriteCostPerMTok = pricing.cacheWriteCostPerMTok;
    46→  const cacheReadCostPerMTok = pricing.cacheReadCostPerMTok;
    47→
    48→  // Convert to actual costs for the given token count
    49→  const tokenMultiplier = cacheTokens / 1_000_000;
    50→
    51→  const cacheWriteCost = cacheWriteCostPerMTok * tokenMultiplier;
    52→  const cacheReadCostPerUse = cacheReadCostPerMTok * tokenMultiplier;
    53→  const inputCostPerUse = inputCostPerMTok * tokenMultiplier;
    54→
    55→  // Savings per reuse = input cost - cache read cost
    56→  const savingsPerReuse = inputCostPerUse - cacheReadCostPerUse;
    57→
    58→  // Break-even: when cache write cost = cumulative savings
    59→  // cacheWriteCost = savingsPerReuse * breakEvenReuses
    60→  const breakEvenReuses = savingsPerReuse > 0
    61→    ? cacheWriteCost / savingsPerReuse
    62→    : Infinity;
    63→
    64→  // Total costs for the scenario
    65→  // With caching: write once + read N times
    66→  const totalWithCaching = cacheWriteCost + (cacheReadCostPerUse * reuseCount);
    67→
    68→  // Without caching: pay full input cost each time
    69→  const totalWithoutCaching = inputCostPerUse * (reuseCount + 1); // +1 for initial use
    70→
    71→  const netSavings = totalWithoutCaching - totalWithCaching;
    72→  const savingsPercent = totalWithoutCaching > 0
    73→    ? (netSavings / totalWithoutCaching) * 100
    74→    : 0;
    75→
    76→  const shouldCache = reuseCount >= breakEvenReuses;
    77→
    78→  // Generate recommendation
    79→  let recommendation: string;
    80→  if (reuseCount === 0) {
    81→    recommendation = "No reuses planned - caching would only add cost";
    82→  } else if (shouldCache) {
    83→    recommendation = `Cache it! You'll save ${formatCost(netSavings)} (${savingsPercent.toFixed(0)}%)`;
    84→  } else {
    85→    const reusesNeeded = Math.ceil(breakEvenReuses) - reuseCount;
    86→    recommendation = `Not worth caching yet. Need ${reusesNeeded} more reuse${reusesNeeded > 1 ? 's' : ''} to break even`;
    87→  }
    88→
    89→  return {
    90→    cacheWriteCost,
    91→    cacheReadCostPerUse,
    92→    inputCostPerUse,
    93→    savingsPerReuse,
    94→    breakEvenReuses,
    95→    totalWithCaching,
    96→    totalWithoutCaching,
    97→    netSavings,
    98→    savingsPercent,
    99→    shouldCache,
   100→    recommendation,
   101→  };
   102→}
   103→
   104→/**
   105→ * Calculate break-even point for a given model
   106→ */
   107→export function calculateBreakeven(model: string): {
   108→  breakEvenReuses: number;
   109→  writeMultiplier: number;
   110→  readMultiplier: number;
   111→} {
   112→  const pricing = getPricingTier(model);
   113→
   114→  // Write costs writeMultiplier times input
   115→  const writeMultiplier = pricing.cacheWriteCostPerMTok / pricing.inputCostPerMTok;
   116→
   117→  // Read costs readMultiplier times input
   118→  const readMultiplier = pricing.cacheReadCostPerMTok / pricing.inputCostPerMTok;
   119→
   120→  // Break-even formula:
   121→  // writeMultiplier * input = (1 - readMultiplier) * input * reuses
   122→  // reuses = writeMultiplier / (1 - readMultiplier)
   123→  const breakEvenReuses = writeMultiplier / (1 - readMultiplier);
   124→
   125→  return {
   126→    breakEvenReuses,
   127→    writeMultiplier,
   128→    readMultiplier,
   129→  };
   130→}
   131→
   132→/**
   133→ * Generate cost comparison data for charting
   134→ */
   135→export function generateCostComparisonData(
   136→  cacheTokens: number,
   137→  model: string,
   138→  maxReuses: number = 10
   139→): Array<{ reuses: number; withCaching: number; withoutCaching: number }> {
   140→  const data: Array<{ reuses: number; withCaching: number; withoutCaching: number }> = [];
   141→
   142→  for (let reuses = 0; reuses <= maxReuses; reuses++) {
   143→    const analysis = analyzeCaching({ cacheTokens, reuseCount: reuses, model });
   144→    data.push({
   145→      reuses,
   146→      withCaching: analysis.totalWithCaching,
   147→      withoutCaching: analysis.totalWithoutCaching,
   148→    });
   149→  }
   150→
   151→  return data;
   152→}
   153→
   154→/**
   155→ * Calculate optimal cache strategy for a given budget
   156→ */
   157→export function optimizeCacheForBudget(
   158→  budget: number,
   159→  cacheTokens: number,
   160→  model: string
   161→): { maxReuses: number; costPerReuse: number } {
   162→  const analysis = analyzeCaching({ cacheTokens, reuseCount: 1, model });
   163→
   164→  // With caching: budget = writeCost + (readCost * reuses)
   165→  // reuses = (budget - writeCost) / readCost
   166→  const maxReusesWithCaching = Math.floor(
   167→    (budget - analysis.cacheWriteCost) / analysis.cacheReadCostPerUse
   168→  );
   169→
   170→  // Without caching: budget = inputCost * uses
   171→  const maxUsesWithoutCaching = Math.floor(budget / analysis.inputCostPerUse);
   172→
   173→  // Return whichever allows more uses
   174→  if (maxReusesWithCaching > maxUsesWithoutCaching) {
   175→    return {
   176→      maxReuses: maxReusesWithCaching,
   177→      costPerReuse: analysis.cacheReadCostPerUse,
   178→    };
   179→  }
   180→
   181→  return {
   182→    maxReuses: maxUsesWithoutCaching - 1, // -1 because first use counts
   183→    costPerReuse: analysis.inputCostPerUse,
   184→  };
   185→}
