     1→/**
     2→ * Known AI model profiles with context window sizes and metadata.
     3→ * Used to auto-detect the active model and set the correct budget.
     4→ */
     5→
     6→export interface ModelProfile {
     7→  id: string;
     8→  label: string;
     9→  provider: 'anthropic' | 'openai' | 'google' | 'other';
    10→  contextWindow: number;   // tokens
    11→  maxOutput: number;        // max output tokens
    12→  rotThreshold: number;     // chat turns before context rot risk
    13→}
    14→
    15→/**
    16→ * Built-in model profiles.
    17→ * Context windows and rot thresholds based on published benchmarks.
    18→ */
    19→export const MODEL_PROFILES: ModelProfile[] = [
    20→  // Anthropic
    21→  { id: 'claude-opus-4.6',     label: 'Claude Opus 4.6',     provider: 'anthropic', contextWindow: 1000000, maxOutput: 32000, rotThreshold: 40 },
    22→  { id: 'claude-sonnet-4.5',   label: 'Claude Sonnet 4.5',   provider: 'anthropic', contextWindow: 200000,  maxOutput: 16000, rotThreshold: 20 },
    23→  { id: 'claude-sonnet-4',     label: 'Claude Sonnet 4',     provider: 'anthropic', contextWindow: 200000,  maxOutput: 16000, rotThreshold: 20 },
    24→  { id: 'claude-haiku-4.5',    label: 'Claude Haiku 4.5',    provider: 'anthropic', contextWindow: 200000,  maxOutput: 64000,  rotThreshold: 15 },
    25→
    26→  // OpenAI
    27→  { id: 'gpt-5.2',             label: 'GPT-5.2',             provider: 'openai',    contextWindow: 256000,  maxOutput: 32000, rotThreshold: 30 },
    28→  { id: 'gpt-5.2-codex',       label: 'GPT-5.2 Codex',       provider: 'openai',    contextWindow: 256000,  maxOutput: 32000, rotThreshold: 30 },
    29→  { id: 'gpt-5.1',             label: 'GPT-5.1',             provider: 'openai',    contextWindow: 256000,  maxOutput: 32000, rotThreshold: 25 },
    30→  { id: 'gpt-5-mini',          label: 'GPT-5 Mini',          provider: 'openai',    contextWindow: 256000,  maxOutput: 32000, rotThreshold: 20 },
    31→  { id: 'gpt-4.1',             label: 'GPT-4.1',             provider: 'openai',    contextWindow: 1047576, maxOutput: 32768, rotThreshold: 20 },
    32→  { id: 'o3',                  label: 'o3',                  provider: 'openai',    contextWindow: 200000,  maxOutput: 100000, rotThreshold: 20 },
    33→  { id: 'o4-mini',             label: 'o4-mini',             provider: 'openai',    contextWindow: 200000,  maxOutput: 100000, rotThreshold: 15 },
    34→
    35→  // Google
    36→  { id: 'gemini-3-pro',        label: 'Gemini 3 Pro',        provider: 'google',    contextWindow: 1048576, maxOutput: 65536, rotThreshold: 30 },
    37→  { id: 'gemini-3-flash',      label: 'Gemini 3 Flash',      provider: 'google',    contextWindow: 1048576, maxOutput: 65536, rotThreshold: 25 },
    38→  { id: 'gemini-2.5-pro',      label: 'Gemini 2.5 Pro',      provider: 'google',    contextWindow: 1048576, maxOutput: 65536, rotThreshold: 20 },
    39→];
    40→
    41→/** Default model when nothing is detected */
    42→export const DEFAULT_MODEL_ID = 'claude-opus-4.6';
    43→
    44→/**
    45→ * Try to find a matching model profile by partial ID or label match.
    46→ * Priority: exact id → exact label → startsWith → contains.
    47→ */
    48→export function findModel(query: string): ModelProfile | undefined {
    49→  const q = query.toLowerCase().replace(/[^a-z0-9.]/g, '');
    50→  if (!q) return undefined;
    51→
    52→  // 1. Exact match on normalized id
    53→  const exact = MODEL_PROFILES.find(m =>
    54→    m.id.toLowerCase().replace(/[^a-z0-9.]/g, '') === q
    55→  );
    56→  if (exact) return exact;
    57→
    58→  // 2. Exact match on normalized label
    59→  const labelExact = MODEL_PROFILES.find(m =>
    60→    m.label.toLowerCase().replace(/[^a-z0-9.]/g, '') === q
    61→  );
    62→  if (labelExact) return labelExact;
    63→
    64→  // 3. Starts-with on id or label
    65→  const startsWith = MODEL_PROFILES.find(m => {
    66→    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
    67→    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
    68→    return mid.startsWith(q) || mlabel.startsWith(q);
    69→  });
    70→  if (startsWith) return startsWith;
    71→
    72→  // 4. Contains match (fallback)
    73→  return MODEL_PROFILES.find(m => {
    74→    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
    75→    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
    76→    return mid.includes(q) || mlabel.includes(q) || q.includes(mid);
    77→  });
    78→}
    79→
    80→/**
    81→ * Get a model profile by exact ID, falling back to default.
    82→ */
    83→export function getModel(id: string): ModelProfile {
    84→  return MODEL_PROFILES.find(m => m.id === id)
    85→    || MODEL_PROFILES.find(m => m.id === DEFAULT_MODEL_ID)!;
    86→}
    87→

