    21→Tokalator — real Claude BPE token counting
    22→
    23→Usage:
    24→  tokalator count [--model <id>] <file> [<file>...]
    25→  tokalator count [--model <id>] --text "<text>"
    26→  tokalator budget [--model <id>] [--turns <n>] [--instructions <n>] <file> [<file>...]
    27→  tokalator preview [--model <id>] <current_tokens>
    28→  tokalator models
    29→
    30→Commands:
    31→  count     Count tokens in one or more files (or raw text via --text)
    32→  budget    Full budget breakdown: files + system overhead + conversation
    33→  preview   Preview estimated token cost of the next chat turn
    34→  models    List available Claude model profiles
    35→
    36→Options:
    37→  --model <id>          Claude model ID (default: claude-opus-4.6)
    38→  --turns <n>           Chat turns so far, for budget overhead (default: 0)
    39→  --instructions <n>    Instruction files attached (default: 0)
    40→  --text "<text>"       Count tokens in a raw string instead of a file
    41→  --help, -h            Show this help
    42→
    43→Examples:
    44→  tokalator count src/main.ts
    45→  tokalator count --model claude-sonnet-4.5 src/**/*.ts
    46→  tokalator count --text "Hello, world!"
    47→  tokalator budget --turns 5 src/index.ts src/utils.ts
    48→  tokalator preview 42000
    49→  tokalator preview --model claude-haiku-4.5 18000
    50→  tokalator models
    51→`.trim();
    52→
    53→// ── Argument parsing ──────────────────────────────────────────────────────────
    54→
    55→function parseArgs(argv: string[]): {
    56→  command: string;
    57→  model?: string;
    58→  turns: number;
    59→  instructions: number;
    60→  text?: string;
    61→  positional: string[];
    62→} {
    63→  const args = argv.slice(2);
    64→  let command = '';
    65→  let model: string | undefined;
    66→  let turns = 0;
    67→  let instructions = 0;
    68→  let text: string | undefined;
    69→  const positional: string[] = [];
    70→
    71→  for (let i = 0; i < args.length; i++) {
    72→    const arg = args[i];
    73→    if (arg === '--help' || arg === '-h') {
    74→      console.log(HELP);
    75→      process.exit(0);
    76→    } else if (arg === '--model' && args[i + 1]) {
    77→      model = args[++i];
    78→    } else if (arg === '--turns' && args[i + 1]) {
    79→      turns = parseInt(args[++i], 10);
    80→    } else if (arg === '--instructions' && args[i + 1]) {
    81→      instructions = parseInt(args[++i], 10);
    82→    } else if (arg === '--text' && args[i + 1]) {
    83→      text = args[++i];
    84→    } else if (!arg.startsWith('-') && !command) {
    85→      command = arg;
    86→    } else if (!arg.startsWith('-')) {
    87→      positional.push(arg);
    88→    }
    89→  }
    90→
    91→  return { command, model, turns, instructions, text, positional };
    92→}
    93→
    94→// ── Main ──────────────────────────────────────────────────────────────────────
    95→
    96→async function main(): Promise<void> {
    97→  const { command, model, turns, instructions, text, positional } = parseArgs(process.argv);
    98→
    99→  if (!command) {
   100→    console.log(HELP);
   101→    process.exit(0);
   102→  }
   103→
   104→  const tokenizer = new TokenizerService();
   105→
   106→  switch (command) {
   107→    case 'count': {
   108→      if (text) {
   109→        const result = await countTokens({ text, model }, tokenizer);
   110→        console.log(result);
   111→        break;
   112→      }
   113→      if (positional.length === 0) {
   114→        console.error('Error: provide at least one file path, or use --text "<text>"');
   115→        process.exit(1);
   116→      }
   117→      // Count each file, print results
   118→      for (const file of positional) {
   119→        const result = await countTokens({ file, model }, tokenizer);
   120→        if (positional.length > 1) {
   121→          console.log(`\n── ${file} ──`);
   122→        }
   123→        console.log(result);
   124→      }
   125→      break;
   126→    }
   127→
   128→    case 'budget': {
   129→      if (positional.length === 0) {
   130→        console.error('Error: provide at least one file path');
   131→        process.exit(1);
   132→      }
   133→      const result = await estimateBudget(
   134→        { files: positional, model, chat_turns: turns, instruction_files: instructions },
   135→        tokenizer,
   136→      );
   137→      console.log(result);
   138→      break;
   139→    }
   140→
   141→    case 'preview': {
   142→      const raw = positional[0];
   143→      if (!raw || isNaN(Number(raw))) {
   144→        console.error('Error: provide current token count as a number\n  tokalator preview 42000');
   145→        process.exit(1);
   146→      }
   147→      const result = previewTurn({ current_tokens: parseInt(raw, 10), model });
   148→      console.log(result);
   149→      break;
   150→    }
   151→
   152→    case 'models': {
   153→      console.log(listModels());
   154→      break;
   155→    }
   156→
   157→    default:
   158→      console.error(`Unknown command: "${command}"\n`);
   159→      console.log(HELP);
   160→      process.exit(1);
   161→  }
   162→
   163→  tokenizer.dispose();
   164→}
   165→
   166→main().catch(err => {
   167→  console.error('Error:', err instanceof Error ? err.message : String(err));
   168→  process.exit(1);
   169→});
