\label{tab:billing-full}
\begin{tabular}{@{} l l r r r @{}}
\toprule
\textbf{Phase} & \textbf{Product} & \textbf{Volume} & \textbf{Gross (\$)} & \textbf{Net (\$)} \\
\midrule
