\quad\textit{Peak: Feb~11} & & \textit{205 req} & \textit{8.20} & \textit{8.20} \\
Feb~12--Mar~7 \textit{(organic tail)} & Copilot premium request & 502 req & 20.08 & 3.36 \\
Feb~6--Mar~7 & GitHub Actions Linux & 261 min & 1.57 & 0.00 \\
\midrule
\textbf{Total} & & \textbf{1{,}413 req + 261 min} & \textbf{58.09} & \textbf{28.36} \\
\bottomrule
